/**
 * Lower-bound binary search over `[0, length)`: the first index where `predicate` holds, or `length`.
 * `predicate` must be monotonic (`false` for a prefix, then `true`), e.g. "first item at or
 * after a timestamp" over a sorted array.
 */
export declare function lowerBound(length: number, predicate: (index: number) => boolean): number;
export declare function locateOnPlateauAlternating<T>(items: readonly T[], needle: T, compare: (left: T, right: T) => number, getItemId: (x: T) => string, insertionIndex: number): number;
export declare function locateOnPlateauScanOneSide<T>(items: readonly T[], needle: T, compare: (left: T, right: T) => number, getItemId: (x: T) => string, insertionIndex: number): number;
